    AN0,BS,BW,AM0,BMS,BMW = (T[k] for k in ('AN0','BS','BW','AM0','BMS','BMW'))
    nz = lambda q: min(AN0[q], BS[q]+5, BW[q]+4)
    mz = lambda q: min(AM0[q], BMS[q]+5, BMW[q]+4)
